mapper.select:
SELECT ra.id, rad.id as detailId, ra.code, ra.type, ra.channel_id AS channelId, ra.channel_name AS channelName, ra.status AS status, ra.source_code AS sourceCode, rad.sku_id AS skuId, rad.sku_no AS skuNo, rad.bom_version AS bomVersion, rad.requisition_qty AS requisitionQty, rad.approve_qty AS approveQty, rad.picking_qty AS pickingQty, rad.virtual_frozen_qty AS virtualFrozenQty, ra.requisition_warehouse_id AS requisitionWarehouseId, ra.requisition_warehouse_name AS requisitionWarehouseName, rad.from_warehouse_id AS fromWarehouseId, rad.from_warehouse_name AS fromWarehouseName, rad.from_virtual_warehouse_id AS fromVirtualWarehouseId, rad.from_virtual_warehouse_name AS fromVirtualWarehouseName, rad.to_warehouse_id AS toWarehouseId, rad.to_warehouse_name AS toWarehouseName, ra.create_user_name AS createUserName, ra.handle_user_name AS handleUserName, ra.handle_time AS handleTime, ra.create_time AS createTime, rad.platform_sku as thirdWarehouseSku, rad.platform_sku as platformSku, rad.platform_spu as platformProductId, rad.platform_fn_sku as platformFnSku, ra.fba_shipment_code as fbaShipmentCode, (select sum(wcd.pack_qty) from wms_carton_detail wcd inner join wms_carton wc on wcd.main_id = wc.id and wc.is_deleted = false where wc.packing_task_id = pt.id and wcd.is_deleted = false and wcd.sku_id = rad.sku_id) as packingQty, pt.packing_status as packingStatus, (select id from fba_shipment fs where fs.is_deleted = false and fs.code = ra.fba_shipment_code limit 1) as shipmentId FROM requisition_application ra INNER JOIN requisition_application_detail rad ON rad.main_id = ra.id AND rad.is_deleted = FALSE LEFT JOIN packing_task pt on pt.source_id = ra.id and pt.is_deleted = false WHERE ${params.sqlMap.default} and ra.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
ra.create_time desc

SELECT ra.id AS sourceId, ra.code AS sourceCode, rad.id AS sourceDetailId, ra.requisition_warehouse_id AS requisitionWarehouseId, ra.requisition_warehouse_name AS requisitionWarehouseName, ra.type, rad.from_virtual_warehouse_id as fromVirtualWarehouseId, rad.from_virtual_warehouse_name as fromVirtualWarehouseName, ra.status AS status, rad.sku_id, rad.sku_no, rad.bom_version, rad.requisition_qty AS requisitionQty, rad.approve_qty AS approveQty FROM requisition_application ra LEFT JOIN requisition_application_detail rad ON rad.main_id = ra.id AND rad.is_deleted = FALSE WHERE ra.is_deleted = FALSE
AND ra.id IN
#{id}

SELECT ra.id AS sourceId, ra.code AS sourceCode, rad.id AS sourceDetailId, ra.requisition_warehouse_id AS requisitionWarehouseId, ra.requisition_warehouse_name AS requisitionWarehouseName, ra.status AS status, rad.requisition_warehouse_location AS requisitionWarehouseLocation, rad.to_warehouse_id AS pickingWarehouseId, rad.to_warehouse_name AS pickingWarehouseName, rad.to_warehouse_id AS toWarehouseId, rad.to_warehouse_name AS toWarehouseName, rad.sku_id, rad.sku_no, rad.bom_version, rad.approve_qty AS approveQty, rad.picking_qty AS pickingQty FROM requisition_application_detail rad LEFT JOIN requisition_application ra ON rad.main_id = ra.id AND rad.is_deleted = FALSE WHERE ra.is_deleted = FALSE
AND ra.id IN
#{id}

SELECT ra.id, rad.id as detailId, ra.code, ra.type, ra.channel_id AS channelId, ra.channel_name AS channelName, ra.status AS status, ra.source_code AS sourceCode, rad.sku_id AS skuId, rad.sku_no AS skuNo, rad.bom_version AS bomVersion, rad.requisition_qty AS requisitionQty, rad.approve_qty AS approveQty, rad.picking_qty AS pickingQty, rad.virtual_frozen_qty AS virtualFrozenQty, ra.requisition_warehouse_id AS requisitionWarehouseId, ra.requisition_warehouse_name AS requisitionWarehouseName, rad.from_warehouse_id AS fromWarehouseId, rad.from_warehouse_name AS fromWarehouseName, rad.from_virtual_warehouse_id AS fromVirtualWarehouseId, rad.from_virtual_warehouse_name AS fromVirtualWarehouseName, rad.to_warehouse_id AS toWarehouseId, rad.to_warehouse_name AS toWarehouseName, ra.create_user_name AS createUserName, ra.handle_user_name AS handleUserName, ra.handle_time AS handleTime, ra.create_time AS createTime, rad.platform_sku as thirdWarehouseSku, rad.platform_sku as platformSku, rad.platform_spu as platformProductId, rad.platform_fn_sku as platformFnSku, ra.fba_shipment_code as fbaShipmentCode, (select sum(wcd.pack_qty) from wms_carton_detail wcd inner join wms_carton wc on wcd.main_id = wc.id and wc.is_deleted = false where wc.packing_task_id = pt.id and wcd.is_deleted = false and wcd.sku_id = rad.sku_id) as packingQty, pt.packing_status as packingStatus, (select id from fba_shipment fs where fs.is_deleted = false and fs.code = ra.fba_shipment_code limit 1) as shipmentId FROM requisition_application ra INNER JOIN requisition_application_detail rad ON rad.main_id = ra.id AND rad.is_deleted = FALSE LEFT JOIN packing_task pt on pt.source_id = ra.id and pt.is_deleted = false WHERE ${params.sqlMap.default} and ra.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
ra.create_time desc

select ra.id AS sourceId, rad.id AS sourceDetailId, ra.code AS sourceCode, ra.requisition_warehouse_id AS deliveryWarehouseId, ra.requisition_warehouse_name AS deliveryWarehouseName, ra.channel_id AS toWarehouseId, ra.channel_name AS toWarehouseName, rad.sku_id, rad.sku_no, rad.approve_qty AS planQty, rad.picking_qty AS deliveryQty, ra.type, rad.platform_sku as platformSku, rad.platform_sku_name as platformSkuName, ra.status as status, ra.source_id as deliveryPlanId, rad.source_detail_id as deliveryPlanDetailId, rad.platform_fn_sku as fnSku, rad.platform_spu as platformSpuNo, ra.fba_shipment_code from requisition_application ra inner join requisition_application_detail rad on ra.id = rad.main_id and rad.is_deleted = false where ra.is_deleted = false
AND ra.id IN
#{id}

select rad.id AS detailId, rad.sku_no AS skuNo, rad.sku_id AS skuId, rad.approve_qty AS planQty, rad.picking_qty AS pickedQuantity, rad.approve_qty - rad.picking_qty AS unpickedQuantity from requisition_application ra inner join requisition_application_detail rad on ra.id = rad.main_id and rad.is_deleted = false where ra.is_deleted = false and ra.id = #{id} and rad.approve_qty > rad.picking_qty
and rad.sku_no not in
#{sku}

with erp_packing as ( SELECT DISTINCT wc.id as cartonId, wc.packing_task_id as taskId, wc.box_no as boxNo, (select string_agg(wcd.sku_no|| '*' || wcd.pack_qty, ';') from wms_carton_detail wcd where wcd.is_deleted = false and wcd.main_id = wc.id) as packingSku, (select string_agg(ptd.fn_sku|| '*' || wcd.pack_qty, ';') from wms_carton_detail wcd inner join packing_task_detail ptd on ptd.sku_id = wcd.sku_id and ptd.main_id = wc.packing_task_id where wcd.is_deleted = false and wcd.main_id = wc.id and ptd.is_deleted = false ) as packingFnSku FROM wms_carton wc WHERE wc.is_deleted = FALSE and wc.id in
#{id}
), fba_packing as ( SELECT fs.id as fbaShipmentId,fs.code as fbaShipmentCode, fsp.box_no as fbaBoxNo, fsp.carton_id as erpCartonId, string_agg(fsp.sku_no|| '*' || fsp.qty,';') AS fbaPackingSku, string_agg(fsp.fn_sku|| '*' || fsp.qty,';') AS fbaPackingFnSku, (select fmd.code from first_mile_delivery fmd inner join first_mile_delivery_detail fmdd on fmd.id = fmdd.main_id and fmdd.is_deleted = false where fmd.is_deleted = false and fmdd.fba_shipment_code = fs.code limit 1) as deliveryCode from fba_shipment_packing fsp inner join fba_shipment fs on fsp.main_id = fs.id where fsp.is_deleted = false and fsp.carton_id in
#{id}
group by fsp.box_no,fsp.carton_id,fs.code,fs.id ) SELECT ep.taskId,ep.cartonId,ep.boxNo,ep.packingSku,ep.packingFnSku, fp.fbaShipmentCode,fp.fbaBoxNo,fp.fbaPackingSku,fp.fbaPackingFnSku,fp.deliveryCode,fp.fbaShipmentId from erp_packing ep left join fba_packing fp on ep.cartonId = fp.erpCartonId order by ep.boxNo

with erp_packing as ( SELECT ptd.fn_sku,sum(wcd.pack_qty) as pack_qty FROM wms_carton wc inner join packing_task_detail ptd on ptd.main_id = wc.packing_task_id and ptd.is_deleted = false inner join wms_carton_detail wcd on wcd.main_id = wc.id and wcd.is_deleted = false and wcd.sku_id = ptd.sku_id and ptd.fn_sku = wcd.fn_sku WHERE wc.is_deleted = FALSE and wc.id in
#{id}
group by ptd.fn_sku ) SELECT fsd.main_id as fbaShipmentId, fsd.asin, fsd.msku, fsd.fn_sku as fnSku, fsd.sku_id as skuId, fsd.sku_no as skuNo, fsd.declare_qty as declareQty, COALESCE(ep.pack_qty,0) as associatedDeliveryQty, COALESCE(ep.pack_qty,0) - fsd.declare_qty as diffQty from fba_shipment_detail fsd left join erp_packing ep on ep.fn_sku = fsd.fn_sku where fsd.main_id = #{params.fbaShipmentId} and fsd.is_deleted = false
